//! Deterministic Markdown contract documentation generator.
//!
//! Emits checked-in, LF-only Markdown reference pages (`index.md` and one `v<major>_<minor>.md`
//! per live version) with HTML-comment ownership headers (`<!-- @generated by witforge (doc,
//! <namespace>:<name>); do not edit. -->`), stability badges, wire numbers, reserved wire slots,
//! pinned dependencies, worlds, and adjacent version-diff tables.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use anyhow::{Context, Result};

use crate::diff::{self, ChangeKind, DecodeVerdict};
use crate::emit::docs::{normalize_lines, sanitize_markdown_inline, sanitize_rust_lines};
use crate::emit::output::{
    GeneratedFileFinding, GeneratedFiles, ensure_outside_wit_root, html_comment_header,
};
use crate::emit::versions::{Version, load_versions_with_released};
use crate::emit::{TypeRenderStyle, render_type, type_kind_name, type_shape};
use crate::load_root_released_manifest;
use crate::model::{Interface, Model, Stability, TypeDef, TypeDefKind};

fn header_for(namespace: &str, name: &str) -> String {
    html_comment_header("doc", namespace, name)
}

/// Plan the complete Markdown documentation output for a WIT root without writing anything.
///
/// # Errors
///
/// Returns the same validation and I/O errors as [`crate::emit::rust::plan`].
pub fn plan(wit_root: &Path) -> Result<GeneratedFiles> {
    plan_with_released(wit_root, None)
}

/// Plan the Markdown documentation output for `wit_root`, using an optional explicit
/// released-version manifest path (`--released`).
///
/// # Errors
///
/// Returns the same errors as [`plan`].
pub fn plan_with_released(wit_root: &Path, released: Option<&Path>) -> Result<GeneratedFiles> {
    let versions = load_versions_with_released(wit_root, released)?;
    let manifest = load_root_released_manifest(wit_root, released)?;
    plan_versions(&versions, &manifest)
}

/// Generate Markdown documentation under `out`.
///
/// # Errors
///
/// Returns an error for invalid input, an output root inside the WIT tree, or an I/O failure.
pub fn generate(wit_root: &Path, out: &Path) -> Result<()> {
    ensure_outside_wit_root(wit_root, out)?;
    plan(wit_root)?.write(out)
}

/// Check generated Markdown documentation under `out` without writing.
///
/// # Errors
///
/// Returns an error for invalid input or an unreadable output root.
pub fn check(wit_root: &Path, out: &Path) -> Result<Vec<GeneratedFileFinding>> {
    ensure_outside_wit_root(wit_root, out)?;
    plan(wit_root)?.check(out)
}

/// Check generated Markdown documentation under `out` without writing, attaching
/// `regenerate_command` to every finding.
///
/// # Errors
///
/// Returns the same errors as [`check`].
pub fn check_with_command(
    wit_root: &Path,
    out: &Path,
    regenerate_command: &str,
) -> Result<Vec<GeneratedFileFinding>> {
    ensure_outside_wit_root(wit_root, out)?;
    plan(wit_root)?.check_with_command(out, regenerate_command)
}

fn plan_versions(
    versions: &[Version],
    manifest: &crate::ReleasedManifest,
) -> Result<GeneratedFiles> {
    let package = &versions
        .first()
        .context("no version directories found under WIT root")?
        .model
        .package;
    let header = header_for(&package.namespace, &package.name);
    let mut files = GeneratedFiles::new(&header);

    let index = render_index(&header, versions, manifest)?;
    files.insert("index.md", index)?;

    for version in versions {
        let dir_name = version
            .directory
            .file_name()
            .and_then(std::ffi::OsStr::to_str)
            .unwrap_or("unknown");
        let is_released = manifest.contains(dir_name);
        let page = render_version_page(&header, version, dir_name, is_released)?;
        let filename = format!(
            "v{}_{}.md",
            version.major, version.model.package.version.minor
        );
        files.insert(filename, page)?;
    }

    Ok(files)
}

#[allow(clippy::too_many_lines)]
fn render_index(
    header: &str,
    versions: &[Version],
    manifest: &crate::ReleasedManifest,
) -> Result<String> {
    let package = &versions[0].model.package;
    let pkg_id = format!("{}:{}", package.namespace, package.name);
    let mut out = String::new();
    writeln!(out, "{header}")?;
    writeln!(out)?;
    writeln!(out, "# `{pkg_id}` Contract Reference")?;
    writeln!(out)?;
    writeln!(out, "## Versions")?;
    writeln!(out)?;
    writeln!(
        out,
        "| Version | Directory | Status | Interfaces | Types | Functions | Worlds |"
    )?;
    writeln!(out, "| --- | --- | --- | ---: | ---: | ---: | ---: |")?;
    for version in versions {
        let dir_name = version
            .directory
            .file_name()
            .and_then(std::ffi::OsStr::to_str)
            .unwrap_or("unknown");
        let status = if manifest.contains(dir_name) {
            "released"
        } else {
            "draft"
        };
        let file = format!(
            "v{}_{}.md",
            version.major, version.model.package.version.minor
        );
        let iface_count = version.model.interfaces.len();
        let type_count: usize = version
            .model
            .interfaces
            .iter()
            .map(|iface| iface.types.len())
            .sum();
        let func_count: usize = version
            .model
            .interfaces
            .iter()
            .map(|iface| iface.functions.len())
            .sum();
        let world_count = version.model.worlds.len();
        writeln!(
            out,
            "| [{}]({file}) | `{dir_name}` | {status} | {iface_count} | {type_count} | \
             {func_count} | {world_count} |",
            version.model.package.version
        )?;
    }

    let retired = manifest.retired_directories();
    if !retired.is_empty() {
        writeln!(out)?;
        writeln!(out, "## Retired Versions")?;
        writeln!(out)?;
        for entry in retired {
            writeln!(out, "- `{entry}` (retired)")?;
        }
    }

    if versions.len() >= 2 {
        writeln!(out)?;
        writeln!(out, "## Version Changes")?;
        for pair in versions.windows(2) {
            let old = &pair[0];
            let new = &pair[1];
            let old_released = old
                .directory
                .file_name()
                .and_then(std::ffi::OsStr::to_str)
                .is_some_and(|name| manifest.contains(name));
            let new_released = new
                .directory
                .file_name()
                .and_then(std::ffi::OsStr::to_str)
                .is_some_and(|name| manifest.contains(name));
            let full = diff::compare_full_with_released_flags(
                &old.directory,
                old_released,
                &new.directory,
                new_released,
            )?;
            let report = &full.analysis.report;
            writeln!(out)?;
            writeln!(
                out,
                "### {} -> {}",
                old.model.package.version, new.model.package.version
            )?;
            writeln!(out)?;
            if report.changes.is_empty() {
                writeln!(out, "No contract changes.")?;
            } else {
                writeln!(
                    out,
                    "Summary: {} change(s), {} breaking (wire: {}, source: {}, api: {}); decode: \
                     {} (new<-old: {}, old<-new: {}).",
                    report.summary.changes,
                    report.summary.breaking,
                    report.summary.wire_breaking,
                    report.summary.source_breaking,
                    report.summary.api_breaking,
                    full.decode_summary.breaking,
                    full.decode_summary.new_reads_old_breaking,
                    full.decode_summary.old_reads_new_breaking,
                )?;
                writeln!(out)?;
                writeln!(
                    out,
                    "| Change | Element | Path | Wire # | Compatibility | Detail |"
                )?;
                writeln!(out, "| --- | --- | --- | --- | --- | --- |")?;
                for (change, &verdict) in report.changes.iter().zip(full.decode_verdicts.iter()) {
                    let (kind, detail) = change_summary(change);
                    let wire_num = change
                        .number
                        .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                    let compat = format_compat(change, verdict);
                    let detail_cell = if detail.is_empty() {
                        "-".to_string()
                    } else {
                        escape_table_cell(&detail)
                    };
                    writeln!(
                        out,
                        "| `{kind}` | {} | `{}` | {wire_num} | {compat} | {detail_cell} |",
                        change.element,
                        escape_table_cell(&change.path)
                    )?;
                }
            }
            if !full.conversion_omissions.is_empty() {
                writeln!(out)?;
                writeln!(out, "#### Omitted Cross-Major Conversions")?;
                writeln!(out)?;
                for omission in &full.conversion_omissions {
                    writeln!(
                        out,
                        "- {} -> {} `{}`: {}",
                        omission.from_version,
                        omission.to_version,
                        omission.type_path,
                        omission.reason
                    )?;
                }
            }
        }
    }

    Ok(out)
}

#[allow(clippy::too_many_lines)]
fn render_version_page(
    header: &str,
    version: &Version,
    dir_name: &str,
    is_released: bool,
) -> Result<String> {
    let model = &version.model;
    let pkg_id = format!("{}:{}", model.package.namespace, model.package.name);
    let mut out = String::new();
    writeln!(out, "{header}")?;
    writeln!(out)?;
    writeln!(out, "# `{pkg_id}@{}`", model.package.version)?;
    writeln!(out)?;
    writeln!(out, "[Back to index](index.md)")?;
    writeln!(out)?;
    let status = if is_released { "released" } else { "draft" };
    writeln!(out, "- **Directory:** `{dir_name}`")?;
    writeln!(out, "- **Status:** {status}")?;
    if !model.dependencies.is_empty() {
        let deps: Vec<String> = model
            .dependencies
            .iter()
            .map(|dep| {
                format!(
                    "`{}:{}@{}`",
                    dep.package.namespace, dep.package.name, dep.package.version
                )
            })
            .collect();
        writeln!(out, "- **Dependencies:** {}", deps.join(", "))?;
    }
    write_normalized_docs(&mut out, &model.package.docs)?;

    let wire_numbers: BTreeMap<String, u32> = version
        .lock
        .entries()
        .filter(|(_, entry)| !entry.reserved)
        .map(|(key, entry)| (key.key(), entry.number))
        .collect();

    if !model.interfaces.is_empty() {
        writeln!(out)?;
        writeln!(out, "## Interfaces")?;
        for iface in &model.interfaces {
            render_interface(&mut out, model, &pkg_id, iface, &wire_numbers)?;
        }
    }

    if !model.worlds.is_empty() {
        writeln!(out)?;
        writeln!(out, "## Worlds")?;
        for world in &model.worlds {
            writeln!(out)?;
            writeln!(
                out,
                "### World `{}`{}",
                world.name,
                stability_badge(&world.stability)
            )?;
            write_normalized_docs(&mut out, &world.docs)?;
            if !world.imports.is_empty() {
                writeln!(out)?;
                writeln!(out, "**Imports:**")?;
                writeln!(out)?;
                for imp in &world.imports {
                    writeln!(
                        out,
                        "- `{}`{}",
                        imp.qualified_name(),
                        stability_badge(&imp.stability)
                    )?;
                }
            }
            if !world.exports.is_empty() {
                writeln!(out)?;
                writeln!(out, "**Exports:**")?;
                writeln!(out)?;
                for exp in &world.exports {
                    writeln!(
                        out,
                        "- `{}`{}",
                        exp.qualified_name(),
                        stability_badge(&exp.stability)
                    )?;
                }
            }
        }
    }

    let reserved: Vec<_> = version
        .lock
        .entries()
        .filter(|(_, entry)| entry.reserved)
        .collect();
    if !reserved.is_empty() {
        writeln!(out)?;
        writeln!(out, "## Reserved Wire Numbers")?;
        writeln!(out)?;
        writeln!(out, "| Member | Wire # | Kind | Type |")?;
        writeln!(out, "| --- | ---: | --- | --- |")?;
        for (key, entry) in reserved {
            let ty = entry.ty.as_deref().map_or_else(
                || "-".to_string(),
                |t| format!("`{}`", escape_table_cell(t)),
            );
            writeln!(
                out,
                "| `{}` | `{}` | `{}` | {ty} |",
                escape_table_cell(&key.key()),
                entry.number,
                entry.kind
            )?;
        }
    }

    Ok(out)
}

#[allow(clippy::too_many_lines)]
fn render_interface(
    out: &mut String,
    _model: &Model,
    pkg_id: &str,
    iface: &Interface,
    wire_numbers: &BTreeMap<String, u32>,
) -> Result<()> {
    writeln!(out)?;
    writeln!(
        out,
        "### Interface `{}`{}",
        iface.name,
        stability_badge(&iface.stability)
    )?;
    write_normalized_docs(out, &iface.docs)?;

    for def in &iface.types {
        render_type_def(out, pkg_id, iface, def, wire_numbers)?;
    }

    for func in &iface.functions {
        let method_key = format!("{pkg_id}/{}.{}", iface.name, func.name);
        let method_num = wire_numbers
            .get(&method_key)
            .map_or_else(|| "-".to_string(), |n| format!("#{n}"));
        writeln!(out)?;
        writeln!(
            out,
            "#### Function `{}` (method {method_num}){}",
            func.name,
            stability_badge(&func.stability)
        )?;
        write_normalized_docs(out, &func.docs)?;

        let params_sig: Vec<String> = func
            .params
            .iter()
            .map(|p| {
                format!(
                    "{}: {}",
                    p.name,
                    render_type(&p.ty, TypeRenderStyle::Spaced)
                )
            })
            .collect();
        let ret_sig = func.result.as_ref().map_or_else(String::new, |ty| {
            format!(" -> {}", render_type(ty, TypeRenderStyle::Spaced))
        });
        writeln!(out)?;
        writeln!(out, "Signature: `func({}){ret_sig}`", params_sig.join(", "))?;

        if !func.params.is_empty() {
            writeln!(out)?;
            writeln!(out, "| Parameter | Type | Wire # |")?;
            writeln!(out, "| --- | --- | ---: |")?;
            for param in &func.params {
                let key = format!("{pkg_id}/{}#{}.{}", iface.name, func.name, param.name);
                let num = wire_numbers
                    .get(&key)
                    .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                let ty = render_type(&param.ty, TypeRenderStyle::Spaced);
                writeln!(
                    out,
                    "| `{}` | `{}` | {num} |",
                    escape_table_cell(&param.name),
                    escape_table_cell(&ty)
                )?;
            }
        }
    }

    Ok(())
}

#[allow(clippy::too_many_lines)]
fn render_type_def(
    out: &mut String,
    pkg_id: &str,
    iface: &Interface,
    def: &TypeDef,
    wire_numbers: &BTreeMap<String, u32>,
) -> Result<()> {
    let kind_name = type_kind_name(&def.kind);
    writeln!(out)?;
    writeln!(
        out,
        "#### `{}` (`{kind_name}`){}",
        def.name,
        stability_badge(&def.stability)
    )?;
    write_normalized_docs(out, &def.docs)?;

    let parent_key = format!("{pkg_id}/{}/{}", iface.name, def.name);
    match &def.kind {
        TypeDefKind::Record(fields) => {
            writeln!(out)?;
            writeln!(out, "| Field | Type | Wire # | Description |")?;
            writeln!(out, "| --- | --- | ---: | --- |")?;
            for field in fields {
                let num = wire_numbers
                    .get(&format!("{parent_key}.{}", field.name))
                    .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                let ty = render_type(&field.ty, TypeRenderStyle::Spaced);
                let desc = inline_doc_cell(&field.docs);
                writeln!(
                    out,
                    "| `{}` | `{}` | {num} | {desc} |",
                    escape_table_cell(&field.name),
                    escape_table_cell(&ty)
                )?;
            }
        }
        TypeDefKind::Variant(cases) => {
            writeln!(out)?;
            writeln!(out, "| Case | Payload | Wire # | Description |")?;
            writeln!(out, "| --- | --- | ---: | --- |")?;
            for case in cases {
                let num = wire_numbers
                    .get(&format!("{parent_key}.{}", case.name))
                    .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                let payload = case.payload.as_ref().map_or_else(
                    || "-".to_string(),
                    |ty| {
                        format!(
                            "`{}`",
                            escape_table_cell(&render_type(ty, TypeRenderStyle::Spaced))
                        )
                    },
                );
                let desc = inline_doc_cell(&case.docs);
                writeln!(
                    out,
                    "| `{}` | {payload} | {num} | {desc} |",
                    escape_table_cell(&case.name)
                )?;
            }
        }
        TypeDefKind::Enum(cases) => {
            writeln!(out)?;
            writeln!(out, "| Case | Wire # | Description |")?;
            writeln!(out, "| --- | ---: | --- |")?;
            for case in cases {
                let num = wire_numbers
                    .get(&format!("{parent_key}.{}", case.name))
                    .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                let desc = inline_doc_cell(&case.docs);
                writeln!(
                    out,
                    "| `{}` | {num} | {desc} |",
                    escape_table_cell(&case.name)
                )?;
            }
        }
        TypeDefKind::Flags(flags) => {
            writeln!(out)?;
            writeln!(out, "| Flag | Wire # | Description |")?;
            writeln!(out, "| --- | ---: | --- |")?;
            for flag in flags {
                let num = wire_numbers
                    .get(&format!("{parent_key}.{}", flag.name))
                    .map_or_else(|| "-".to_string(), |n| format!("`{n}`"));
                let desc = inline_doc_cell(&flag.docs);
                writeln!(
                    out,
                    "| `{}` | {num} | {desc} |",
                    escape_table_cell(&flag.name)
                )?;
            }
        }
        TypeDefKind::Alias(_)
        | TypeDefKind::List(_)
        | TypeDefKind::FixedLengthList(..)
        | TypeDefKind::Option(_)
        | TypeDefKind::Result(_)
        | TypeDefKind::Map(..) => {
            writeln!(out)?;
            writeln!(
                out,
                "Definition: `{}`",
                type_shape(&def.kind, TypeRenderStyle::Spaced)
            )?;
        }
    }
    Ok(())
}

fn stability_badge(stability: &Stability) -> String {
    match stability {
        Stability::Unknown => String::new(),
        Stability::Stable { since } => format!(" — `stable` (since `{since}`)"),
        Stability::Unstable { feature } => format!(" — `unstable` (feature `{feature}`)"),
        Stability::Deprecated {
            since,
            feature,
            deprecated,
            ..
        } => match (since, feature) {
            (Some(since), _) => {
                format!(" — `deprecated` (since `{since}`, deprecated `{deprecated}`)")
            }
            (None, Some(feature)) => {
                format!(" — `deprecated` (unstable `{feature}`, deprecated `{deprecated}`)")
            }
            (None, None) => format!(" — `deprecated` (`{deprecated}`)"),
        },
    }
}

fn write_normalized_docs(out: &mut String, docs: &str) -> Result<()> {
    if docs.is_empty() {
        return Ok(());
    }
    let lines = sanitize_rust_lines(docs);
    if lines.is_empty() {
        return Ok(());
    }
    writeln!(out)?;
    for line in lines {
        writeln!(out, "{line}")?;
    }
    Ok(())
}

fn inline_doc_cell(docs: &str) -> String {
    if docs.is_empty() {
        return "-".to_string();
    }
    let lines = normalize_lines(docs);
    if lines.is_empty() {
        return "-".to_string();
    }
    let joined: Vec<&str> = lines
        .iter()
        .map(|line| line.trim())
        .filter(|line| !line.is_empty())
        .collect();
    if joined.is_empty() {
        "-".to_string()
    } else {
        escape_table_cell(&sanitize_markdown_inline(&joined.join(" ")))
    }
}

fn escape_table_cell(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut backslashes = 0usize;
    for ch in text.chars() {
        if ch == '\\' {
            backslashes += 1;
            out.push(ch);
        } else if ch == '|' {
            if backslashes & 1 == 0 {
                out.push('\\');
            }
            backslashes = 0;
            out.push('|');
        } else {
            backslashes = 0;
            out.push(ch);
        }
    }
    out
}

fn change_summary(change: &diff::Change) -> (&'static str, String) {
    match &change.kind {
        ChangeKind::Added { defaulted: true } => ("added-defaulted", String::new()),
        ChangeKind::Added { defaulted: false } => ("added", String::new()),
        ChangeKind::Removed => ("removed", String::new()),
        ChangeKind::Reordered { before, after } => (
            "reordered",
            format!("`{}` -> `{}`", before.join("`, `"), after.join("`, `")),
        ),
        ChangeKind::Retyped { from, to } => ("retyped", format!("`{from}` -> `{to}`")),
        ChangeKind::KindChanged { from, to } => ("kind-changed", format!("`{from}` -> `{to}`")),
        ChangeKind::Renumbered { from, to } => ("renumbered", format!("`{from}` -> `{to}`")),
        ChangeKind::StabilityChanged { from, to } => {
            ("stability-changed", format!("`{from}` -> `{to}`"))
        }
    }
}

fn format_compat(change: &diff::Change, verdict: DecodeVerdict) -> String {
    let mut parts = Vec::new();
    if change.wire_breaking {
        parts.push("wire:BREAKING");
    }
    if change.source_breaking {
        parts.push("source:BREAKING");
    }
    if change.api_breaking {
        parts.push("api:BREAKING");
    }
    match (verdict.new_reads_old, verdict.old_reads_new) {
        (true, true) => {}
        (false, true) => parts.push("decode:BREAKING(new<-old)"),
        (true, false) => parts.push("decode:BREAKING(old<-new)"),
        (false, false) => parts.push("decode:BREAKING(both)"),
    }
    if parts.is_empty() {
        "compatible".to_string()
    } else {
        parts.join(", ")
    }
}
